1	//! Named/indexed, once-per-session direct-child autostart ownership.
2	use crate::{Error, ManagedChild, SpawnJob};
3	use std::os::unix::process::ExitStatusExt;
4	use std::{
5	    ffi::OsString,
6	    io,
7	    path::PathBuf,
8	    sync::{Arc, Condvar, Mutex},
9	    thread::{self, JoinHandle},
10	    time::{Duration, Instant},
11	};
12	
13	pub const MAX_AUTOSTART_ENTRIES: usize = 128;
14	pub const MAX_AUTOSTART_IDENTITIES: usize = 256;
15	pub const MAX_AUTOSTART_PLAN_BYTES: usize = 4 * 1024 * 1024;
16	pub const MAX_AUTOSTART_HISTORY_BYTES: usize = 8 * 1024 * 1024;
17	const GRACE: Duration = Duration::from_millis(250);
18	
19	#[derive(Debug)]
20	pub struct AutostartCommand {
21	    pub id: Option<String>,
22	    pub argv: Vec<String>,
23	    pub restart_on_change: bool,
24	}
25	#[derive(Clone, Debug, PartialEq, Eq)]
26	enum Identity {
27	    Index(usize),
28	    Named(String),
29	}
30	#[derive(Debug)]
31	struct Entry {
32	    identity: Identity,
33	    argv: Arc<Vec<String>>,
34	    bytes: usize,
35	    restart: bool,
36	}
37	/// Construct on a preparation worker. Keeps source-controlled strings out of
38	/// dispatch-time admission and status snapshots. Identity is an optional stable ID, or the legacy entry index.
39	#[derive(Debug)]
40	pub struct AutostartPlan {
41	    generation: u64,
42	    entries: Vec<Entry>,
43	    display: OsString,
44	    ipc: Option<PathBuf>,
45	}
46	impl AutostartPlan {
47	    pub fn prepare(
48	        generation: u64,
49	        commands: Vec<AutostartCommand>,
50	        display: OsString,
51	        ipc: Option<PathBuf>,
52	    ) -> Result<Arc<Self>, Error> {
53	        if generation == 0 || commands.len() > MAX_AUTOSTART_ENTRIES {
54	            return Err(Error::Invalid(
55	                "invalid autostart generation or entry count".into(),
56	            ));
57	        }
58	        crate::validate_environment_value(display.as_encoded_bytes(), "WAYLAND_DISPLAY")?;
59	        if let Some(path) = &ipc {
60	            crate::validate_environment_value(
61	                path.as_os_str().as_encoded_bytes(),
62	                "FLUXWM_SOCKET",
63	            )?;
64	        }
65	        let mut total = 0usize;
66	        let mut entries = Vec::with_capacity(commands.len());
67	        for (index, command) in commands.into_iter().enumerate() {
68	            let identity = match command.id {
69	                Some(id) if !id.is_empty() && id.len() <= 128 && !id.contains('\0') => {
70	                    Identity::Named(id)
71	                }
72	                Some(_) => return Err(Error::Invalid("invalid autostart identity".into())),
73	                None => Identity::Index(index),
74	            };
75	            if entries.iter().any(|e: &Entry| e.identity == identity) {
76	                return Err(Error::Invalid("duplicate autostart identity".into()));
77	            }
78	            flux_core::validate_argv(&command.argv)
79	                .map_err(|_| Error::Invalid("invalid autostart argv".into()))?;
80	            let bytes = command.argv.iter().map(String::len).sum::<usize>();
81	            total = total
82	                .checked_add(bytes)
83	                .ok_or_else(|| Error::Invalid("autostart byte accounting overflow".into()))?;
84	            if total > MAX_AUTOSTART_PLAN_BYTES {
85	                return Err(Error::Invalid(
86	                    "autostart plan exceeds 4MiB argv bytes".into(),
87	                ));
88	            }
89	            entries.push(Entry {
90	                identity,
91	                argv: Arc::new(command.argv),
92	                bytes,
93	                restart: command.restart_on_change,
94	            });
95	        }
96	        Ok(Arc::new(Self {
97	            generation,
98	            entries,
99	            display,
100	            ipc,
101	        }))
102	    }
103	    pub fn generation(&self) -> u64 {
104	        self.generation
105	    }
106	}
107	#[derive(Clone, Debug)]
108	pub struct AutostartStatus {
109	    pub slot: usize,
110	    pub id: Option<String>,
111	    pub index: Option<usize>,
112	    pub desired: bool,
113	    pub attempts: u64,
114	    pub starts: u64,
115	    pub pid: Option<u32>,
116	    pub state: &'static str,
117	    pub change_deferred: bool,
118	    pub error: Option<&'static str>,
119	    pub errno: Option<i32>,
120	    pub exit_code: Option<i32>,
121	    pub exit_signal: Option<i32>,
122	}
123	#[derive(Clone, Debug, Default)]
124	pub struct AutostartSnapshot {
125	    pub requested_generation: Option<u64>,
126	    pub active_generation: Option<u64>,
127	    pub settled: bool,
128	    pub closed: bool,
129	    pub error: Option<&'static str>,
130	    pub entries: Vec<AutostartStatus>,
131	}
132	#[derive(Default)]
133	struct Control {
134	    latest: u64,
135	    pending: Option<Arc<AutostartPlan>>,
136	    discard: Option<Arc<AutostartPlan>>,
137	    reap: bool,
138	    closed: bool,
139	    snapshot: Option<AutostartSnapshot>,
140	}
141	#[derive(Default)]
142	struct Shared {
143	    control: Mutex<Control>,
144	    changed: Condvar,
145	}
146	pub struct AutostartWorker {
147	    shared: Arc<Shared>,
148	    thread: Option<JoinHandle<()>>,
149	}
150	impl AutostartWorker {
151	    pub fn new(notify: impl Fn() + Send + 'static) -> io::Result<Self> {
152	        let shared = Arc::new(Shared::default());
153	        let owned = shared.clone();
154	        let thread = thread::Builder::new()
155	            .name("flux-autostart".into())
156	            .spawn(move || run(owned, notify))?;
157	        Ok(Self {
158	            shared,
159	            thread: Some(thread),
160	        })
161	    }
162	    /// Nonblocking latest-plan admission. QueueFull means retry the same pinned
163	    /// plan after a worker notification. No executable work or argv scans occur.
164	    pub fn try_install(&self, plan: &Arc<AutostartPlan>) -> Result<(), Error> {
165	        let mut c = self
166	            .shared
167	            .control
168	            .lock()
169	            .unwrap_or_else(|e| e.into_inner());
170	        if c.closed || self.thread.as_ref().is_none_or(|t| t.is_finished()) {
171	            return Err(Error::Stopped);
172	        }
173	        if plan.generation <= c.latest {
174	            return Err(Error::Invalid("autostart generation is stale".into()));
175	        }
176	        if c.pending.is_some() && c.discard.is_some() {
177	            return Err(Error::QueueFull);
178	        }
179	        c.latest = plan.generation;
180	        if let Some(old) = c.pending.replace(plan.clone()) {
181	            c.discard = Some(old);
182	        }
183	        self.shared.changed.notify_one();
184	        Ok(())
185	    }
186	    pub fn notify_child_exit(&self) {
187	        let mut c = self
188	            .shared
189	            .control
190	            .lock()
191	            .unwrap_or_else(|e| e.into_inner());
192	        c.reap = true;
193	        self.shared.changed.notify_one();
194	    }
195	    pub fn take_snapshot(&self) -> Option<AutostartSnapshot> {
196	        self.shared
197	            .control
198	            .lock()
199	            .unwrap_or_else(|e| e.into_inner())
200	            .snapshot
201	            .take()
202	    }
203	    /// Seals admission without dropping plans, killing or waiting on dispatch.
204	    pub fn stop(&self) {
205	        let mut c = self
206	            .shared
207	            .control
208	            .lock()
209	            .unwrap_or_else(|e| e.into_inner());
210	        c.closed = true;
211	        self.shared.changed.notify_one();
212	    }
213	    pub fn shutdown(&mut self) -> io::Result<()> {
214	        self.stop();
215	        if let Some(thread) = self.thread.take() {
216	            thread
217	                .join()
218	                .map_err(|_| io::Error::other("autostart worker panicked"))?;
219	        }
220	        Ok(())
221	    }
222	}
223	impl Drop for AutostartWorker {
224	    fn drop(&mut self) {
225	        let _ = self.shutdown();
226	    }
227	}
228	struct Slot {
229	    identity: Identity,
230	    history: Option<Arc<Vec<String>>>,
231	    bytes: usize,
232	    present: bool,
233	    restart_pending: bool,
234	    child: Option<ManagedChild>,
235	    view: AutostartStatus,
236	}
237	impl Slot {
238	    fn new(slot: usize, identity: Identity) -> Self {
239	        Self {
240	            identity: identity.clone(),
241	            history: None,
242	            bytes: 0,
243	            present: false,
244	            restart_pending: false,
245	            child: None,
246	            view: AutostartStatus {
247	                slot,
248	                id: match identity {
249	                    Identity::Named(id) => Some(id),
250	                    Identity::Index(_) => None,
251	                },
252	                index: None,
253	                desired: false,
254	                attempts: 0,
255	                starts: 0,
256	                pid: None,
257	                state: "never-started",
258	                change_deferred: false,
259	                error: None,
260	                errno: None,
261	                exit_code: None,
262	                exit_signal: None,
263	            },
264	        }
265	    }
266	    fn needs_start(&self, e: &Entry) -> bool {
267	        self.view.attempts == 0
268	            || (e.restart
269	                && (self.restart_pending
270	                    || !self.present
271	                    || self.history.as_deref() != Some(e.argv.as_ref())))
272	    }
273	    fn exited(&mut self, status: std::process::ExitStatus) {
274	        self.view.pid = None;
275	        self.view.state = "exited";
276	        self.view.exit_code = status.code();
277	        self.view.exit_signal = status.signal();
278	    }
279	}
280	fn current(shared: &Shared, generation: u64) -> bool {
281	    let c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
282	    !c.closed && c.latest == generation
283	}
284	fn publish(
285	    shared: &Shared,
286	    slots: &[Slot],
287	    active: Option<u64>,
288	    observed: Option<u64>,
289	    settled: bool,
290	    error: Option<&'static str>,
291	    notify: &impl Fn(),
292	) {
293	    let mut snapshot = AutostartSnapshot {
294	        requested_generation: observed,
295	        active_generation: active,
296	        settled,
297	        closed: false,
298	        error,
299	        entries: slots.iter().map(|s| s.view.clone()).collect(),
300	    };
301	    let old = {
302	        let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
303	        snapshot.closed = c.closed;
304	        c.snapshot.replace(snapshot)
305	    };
306	    drop(old);
307	    notify();
308	}
309	fn reap(slots: &mut [Slot]) -> bool {
310	    let mut changed = false;
311	    for slot in slots {
312	        if let Some(child) = slot.child.as_mut() {
313	            match child.try_wait() {
314	                Ok(Some(status)) => {
315	                    slot.exited(status);
316	                    slot.child.take();
317	                    changed = true;
318	                }
319	                Ok(None) => (),
320	                Err(error) => {
321	                    if slot.view.error != Some("owned child reaping failed")
322	                        || slot.view.errno != error.raw_os_error()
323	                    {
324	                        changed = true;
325	                    }
326	                    slot.view.error = Some("owned child reaping failed");
327	                    slot.view.state = "ownership-error";
328	                    slot.view.errno = error.raw_os_error();
329	                }
330	            }
331	        }
332	    }
333	    changed
334	}
335	/// Broadcast TERM before a common grace interval, then retire remaining owned
336	/// children. No waitpid(-1), process-group signalling or descendant claim.
337	fn retire(slots: &mut [Slot], indices: &[usize]) {
338	    for &i in indices {
339	        if let Some(child) = slots[i].child.as_mut() {
340	            match child.try_wait() {
341	                Ok(Some(status)) => slots[i].exited(status),
342	                Ok(None) => {
343	                    // SAFETY: this exclusive unreaped Child keeps its PID from
344	                    // reuse. No external reaper may compete with this owner.
345	                    if unsafe { libc::kill(child.id() as libc::pid_t, libc::SIGTERM) } != 0 {
346	                        slots[i].view.error = Some("owned child termination failed");
347	                        slots[i].view.errno = io::Error::last_os_error().raw_os_error();
348	                    }
349	                }
350	                Err(error) => {
351	                    slots[i].view.error = Some("owned child reaping failed");
352	                    slots[i].view.errno = error.raw_os_error();
353	                }
354	            }
355	        }
356	    }
357	    let deadline = Instant::now() + GRACE;
358	    while Instant::now() < deadline {
359	        let mut live = false;
360	        for &i in indices {
361	            if let Some(child) = slots[i].child.as_mut() {
362	                match child.try_wait() {
363	                    Ok(Some(status)) => {
364	                        slots[i].exited(status);
365	                        slots[i].child.take();
366	                    }
367	                    Ok(None) => live = true,
368	                    Err(_) => {
369	                        live = true;
370	                    }
371	                }
372	            }
373	        }
374	        if !live {
375	            break;
376	        }
377	        thread::sleep(Duration::from_millis(2));
378	    }
379	    for &i in indices {
380	        if let Some(mut child) = slots[i].child.take() {
381	            match child.try_wait() {
382	                Ok(Some(status)) => slots[i].exited(status),
383	                Ok(None) => {
384	                    let _ = child.child.kill();
385	                    match child.wait() {
386	                        Ok(status) => slots[i].exited(status),
387	                        Err(error) => {
388	                            slots[i].view.error = Some("owned child retirement failed");
389	                            slots[i].view.errno = error.raw_os_error();
390	                        }
391	                    }
392	                }
393	                Err(error) => {
394	                    slots[i].view.error = Some("owned child retirement failed");
395	                    slots[i].view.errno = error.raw_os_error();
396	                }
397	            }
398	        }
399	        slots[i].view.pid = None;
400	    }
401	}
402	fn run(shared: Arc<Shared>, notify: impl Fn()) {
403	    let mut slots: Vec<Slot> = Vec::new();
404	    let mut active = None;
405	    let mut observed = None;
406	    let mut settled = true;
407	    let mut plan_error = None;
408	    loop {
409	        let (plan, discard, should_reap, closed) = {
410	            let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
411	            while !c.closed && c.pending.is_none() && c.discard.is_none() && !c.reap {
412	                c = shared.changed.wait(c).unwrap_or_else(|e| e.into_inner());
413	            }
414	            let values = (c.pending.take(), c.discard.take(), c.reap, c.closed);
415	            c.reap = false;
416	            values
417	        };
418	        let discarded = discard.is_some();
419	        drop(discard);
420	        if discarded {
421	            notify();
422	        }
423	        if closed {
424	            break;
425	        }
426	        if should_reap && reap(&mut slots) {
427	            publish(
428	                &shared, &slots, active, observed, settled, plan_error, &notify,
429	            );
430	        }
431	        let Some(plan) = plan else {
432	            continue;
433	        };
434	        if !current(&shared, plan.generation) {
435	            continue;
436	        }
437	        observed = Some(plan.generation);
438	        let added = plan
439	            .entries
440	            .iter()
441	            .filter(|entry| !slots.iter().any(|s| s.identity == entry.identity))
442	            .count();
443	        let mut bytes = 0usize;
444	        for slot in &slots {
445	            if let Some(entry) = plan.entries.iter().find(|e| e.identity == slot.identity) {
446	                bytes += if slot.needs_start(entry) {
447	                    entry.bytes
448	                } else {
449	                    slot.bytes
450	                };
451	            }
452	        }
453	        bytes += plan
454	            .entries
455	            .iter()
456	            .filter(|e| !slots.iter().any(|s| s.identity == e.identity))
457	            .map(|e| e.bytes)
458	            .sum::<usize>();
459	        if slots.len() + added > MAX_AUTOSTART_IDENTITIES || bytes > MAX_AUTOSTART_HISTORY_BYTES {
460	            plan_error = Some("autostart session identity or retained argv budget exceeded");
461	            publish(&shared, &slots, active, observed, true, plan_error, &notify);
462	            continue;
463	        }
464	        for entry in &plan.entries {
465	            if !slots.iter().any(|s| s.identity == entry.identity) {
466	                slots.push(Slot::new(slots.len(), entry.identity.clone()));
467	            }
468	        }
469	        let stop: Vec<_> = slots
470	            .iter()
471	            .enumerate()
472	            .filter_map(|(i, s)| {
473	                let desired = plan.entries.iter().find(|e| e.identity == s.identity);
474	                (s.child.is_some() && desired.is_none_or(|entry| s.needs_start(entry))).then_some(i)
475	            })
476	            .collect();
477	        active = Some(plan.generation);
478	        plan_error = None;
479	        // A superseding plan can arrive during retirement. Preserve the need
480	        // to restart a deliberately retired child even if it restores argv.
481	        for &i in &stop {
482	            slots[i].restart_pending = true;
483	        }
484	        retire(&mut slots, &stop);
485	        for slot in &mut slots {
486	            if !plan.entries.iter().any(|e| e.identity == slot.identity) {
487	                slot.present = false;
488	                slot.restart_pending = false;
489	                slot.history = None;
490	                slot.bytes = 0;
491	                slot.view.desired = false;
492	                slot.view.index = None;
493	                slot.view.change_deferred = false;
494	                slot.view.state = "removed";
495	            }
496	        }
497	        publish(&shared, &slots, active, observed, false, None, &notify);
498	        let mut complete = true;
499	        for (index, entry) in plan.entries.iter().enumerate() {
500	            if !current(&shared, plan.generation) {
501	                complete = false;
502	                break;
503	            }
504	            let slot = slots
505	                .iter_mut()
506	                .find(|s| s.identity == entry.identity)
507	                .expect("reserved identity");
508	            let start = slot.needs_start(entry);
509	            slot.present = true;
510	            slot.view.desired = true;
511	            slot.view.index = Some(index);
512	            slot.view.change_deferred =
513	                !start && slot.history.as_deref() != Some(entry.argv.as_ref());
514	            if !start {
515	                continue;
516	            }
517	            let Some(attempts) = slot.view.attempts.checked_add(1) else {
518	                slot.view.error = Some("autostart attempt counter exhausted");
519	                continue;
520	            };
521	            slot.restart_pending = false;
522	            slot.history = Some(entry.argv.clone());
523	            slot.bytes = entry.bytes;
524	            slot.view.attempts = attempts;
525	            slot.view.error = None;
526	            slot.view.errno = None;
527	            slot.view.exit_code = None;
528	            slot.view.exit_signal = None;
529	            let job = SpawnJob {
530	                operation: plan.generation,
531	                argv: entry.argv.as_ref().clone(),
532	                wayland_display: plan.display.clone(),
533	                ipc_socket: plan.ipc.clone(),
534	            };
535	            match crate::launch(job) {
536	                Ok(child) => {
537	                    slot.view.starts = slot
538	                        .view
539	                        .starts
540	                        .checked_add(1)
541	                        .expect("starts bounded by attempts");
542	                    slot.view.pid = Some(child.id());
543	                    slot.view.state = "running";
544	                    slot.child = Some(child);
545	                }
546	                Err(error) => {
547	                    slot.view.state = "failed";
548	                    slot.view.pid = None;
549	                    slot.view.error = Some("autostart executable could not be started");
550	                    slot.view.errno = error.raw_os_error();
551	                }
552	            }
553	            reap(&mut slots);
554	            publish(&shared, &slots, active, observed, false, None, &notify);
555	        }
556	        settled = complete;
557	        publish(&shared, &slots, active, observed, settled, None, &notify);
558	    }
559	    let indices: Vec<_> = (0..slots.len()).collect();
560	    retire(&mut slots, &indices);
561	    for s in &mut slots {
562	        s.view.state = "stopped";
563	        s.view.pid = None;
564	    }
565	    publish(&shared, &slots, active, observed, true, None, &notify);
566	    let (pending, discard) = {
567	        let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
568	        (c.pending.take(), c.discard.take())
569	    };
570	    drop((pending, discard));
571	}
