574	mod tests {
575	    use super::*;
576	    use std::os::unix::fs::DirBuilderExt;
577	    struct Temp(PathBuf);
578	    impl Temp {
579	        fn new() -> Self {
580	            static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
581	            let path = std::env::temp_dir().join(format!(
582	                "flux-auto-{}-{}",
583	                std::process::id(),
584	                NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
585	            ));
586	            std::fs::DirBuilder::new()
587	                .mode(0o700)
588	                .create(&path)
589	                .unwrap();
590	            Self(path)
591	        }
592	    }
593	    impl Drop for Temp {
594	        fn drop(&mut self) {
595	            let _ = std::fs::remove_dir_all(&self.0);
596	        }
597	    }
598	    fn command(id: &str, arg: &str, restart: bool) -> AutostartCommand {
599	        AutostartCommand {
600	            id: Some(id.into()),
601	            argv: vec!["/bin/sleep".into(), arg.into()],
602	            restart_on_change: restart,
603	        }
604	    }
605	    fn plan(g: u64, commands: Vec<AutostartCommand>) -> Arc<AutostartPlan> {
606	        AutostartPlan::prepare(g, commands, "auto-test".into(), None).unwrap()
607	    }
608	    fn settled(worker: &AutostartWorker, g: u64) -> AutostartSnapshot {
609	        let until = Instant::now() + Duration::from_secs(5);
610	        loop {
611	            worker.notify_child_exit();
612	            if let Some(s) = worker.take_snapshot()
613	                && s.requested_generation == Some(g)
614	                && s.settled
615	            {
616	                return s;
617	            }
618	            assert!(
619	                Instant::now() < until,
620	                "autostart did not settle generation{g}"
621	            );
622	            thread::sleep(Duration::from_millis(2));
623	        }
624	    }
625	    fn reaped(pid: u32) {
626	        let mut status = 0;
627	        assert_eq!(
628	            unsafe { libc::waitpid(pid as libc::pid_t, &mut status, libc::WNOHANG) },
629	            -1
630	        );
631	        assert_eq!(
632	            io::Error::last_os_error().raw_os_error(),
633	            Some(libc::ECHILD)
634	        );
635	    }
636	    #[test]
637	    fn once_restart_named_reorder_removal_and_reintroduction_own_real_children() {
638	        let mut worker = AutostartWorker::new(|| {}).unwrap();
639	        worker
640	            .try_install(&plan(
