1	//! Trusted-host application launching. Never evaluate Lua or split shell strings here.
2	//! Worker and ManagedChild shutdown can wait for the OS; drop outside event dispatch.
3	mod autostart;
4	pub use autostart::*;
5	
6	use calloop::channel::{Channel, SyncSender as CompletionSender};
7	use std::{
8	    ffi::OsString,
9	    fmt, io,
10	    os::unix::{ffi::OsStrExt, process::CommandExt},
11	    path::PathBuf,
12	    process::{Child, Command, ExitStatus},
13	    sync::{
14	        Arc, Condvar, Mutex,
15	        atomic::{AtomicBool, Ordering},
16	        mpsc::{self, Receiver, SyncSender, TrySendError},
17	    },
