26	#[derive(Debug, Clone)]
27	pub struct SpawnJob {
28	    pub operation: u64,
29	    pub argv: Vec<String>,
30	    pub wayland_display: OsString,
31	    pub ipc_socket: Option<PathBuf>,
32	}
33	impl SpawnJob {
34	    pub fn validate(&self) -> Result<(), Error> {
35	        flux_core::validate_argv(&self.argv).map_err(|e| Error::Invalid(e.to_string()))?;
36	        validate_environment_value(self.wayland_display.as_bytes(), "WAYLAND_DISPLAY")?;
37	        if let Some(path) = &self.ipc_socket {
38	            validate_environment_value(path.as_os_str().as_bytes(), "FLUXWM_SOCKET")?;
39	        }
40	        Ok(())
41	    }
42	}
43	fn validate_environment_value(value: &[u8], name: &str) -> Result<(), Error> {
44	    if value.is_empty() || value.len() > 4096 || value.contains(&0) {
45	        return Err(Error::Invalid(format!(
46	            "{name}: expected 1..4096 NUL-free bytes"
47	        )));
48	    }
49	    Ok(())
50	}
51	
52	#[derive(Debug, Clone, PartialEq, Eq)]
53	pub enum Error {
54	    Invalid(String),
55	    QueueFull,
56	    Stopped,
57	}
58	impl fmt::Display for Error {
59	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
60	        match self {
61	            Self::Invalid(message) => f.write_str(message),
62	            Self::QueueFull => f.write_str("application spawn queue is full"),
63	            Self::Stopped => f.write_str("application spawn worker is stopped"),
64	        }
65	    }
66	}
67	impl std::error::Error for Error {}
68	
69	/// Owns one direct child. No external waitpid reaper or SIGCHLD auto-reap may
70	/// compete with this owner. Descendants/process groups require separate policy.
71	#[derive(Debug)]
72	pub struct ManagedChild {
73	    child: Child,
74	}
75	impl ManagedChild {
76	    pub fn id(&self) -> u32 {
77	        self.child.id()
78	    }
79	    pub fn try_wait(&mut self) -> io::Result<Option<ExitStatus>> {
80	        self.child.try_wait()
81	    }
82	    /// Blocking; call outside compositor event dispatch.
83	    pub fn wait(&mut self) -> io::Result<ExitStatus> {
84	        self.child.wait()
85	    }
86	}
87	impl Drop for ManagedChild {
88	    fn drop(&mut self) {
89	        match self.child.try_wait() {
90	            Ok(Some(_)) => return,
91	            // If ownership was violated by an external reaper, do not signal a
92	            // potentially reused PID. This is not successful owned-child cleanup.
93	            Err(error) if error.raw_os_error() == Some(libc::ECHILD) => return,
94	            _ => {}
95	        }
96	        let _ = self.child.kill();
97	        let _ = self.child.wait();
98	    }
99	}
100	
101	#[derive(Debug)]
102	pub struct SpawnOutcome {
103	    pub operation: u64,
104	    pub result: Result<ManagedChild, String>,
105	}
