107	fn command(job: &SpawnJob) -> Command {
108	    let mut command = Command::new(&job.argv[0]);
109	    command.args(&job.argv[1..]);
110	    command.env("WAYLAND_DISPLAY", &job.wayland_display);
111	    command.env_remove("WAYLAND_SOCKET");
112	    command.env_remove("DISPLAY");
113	    match &job.ipc_socket {
114	        Some(path) => {
115	            command.env("FLUXWM_SOCKET", path);
116	        }
117	        None => {
118	            command.env_remove("FLUXWM_SOCKET");
119	        }
120	    }
121	    // Root blocks termination/child-notification signals before backend/worker
122	    // threads. Exec inherits the thread mask unless explicitly changed.
123	    // Only async-signal-safe functions run in this post-fork child hook.
124	    unsafe {
125	        command.pre_exec(|| {
126	            let mut signals: libc::sigset_t = std::mem::zeroed();
127	            if libc::sigemptyset(&mut signals) != 0
128	                || libc::sigaddset(&mut signals, libc::SIGINT) != 0
129	                || libc::sigaddset(&mut signals, libc::SIGTERM) != 0
130	                || libc::sigaddset(&mut signals, libc::SIGCHLD) != 0
131	                || libc::sigprocmask(libc::SIG_UNBLOCK, &signals, std::ptr::null_mut()) != 0
132	            {
133	                return Err(io::Error::last_os_error());
134	            }
135	            Ok(())
136	        });
137	    }
138	    command
139	}
