141	/// Synchronous startup/worker launcher. Command::spawn may wait for filesystem,
142	/// exec or kernel work; never call it from compositor event dispatch.
143	pub fn launch(job: SpawnJob) -> io::Result<ManagedChild> {
144	    job.validate()
145	        .map_err(|error| io::Error::new(io::ErrorKind::InvalidInput, error))?;
146	    command(&job).spawn().map(|child| ManagedChild { child })
147	}
