149	struct Control {
150	    stopping: AtomicBool,
151	    mutex: Mutex<()>,
152	    changed: Condvar,
153	}
154	impl Control {
155	    fn stopped(&self) -> bool {
156	        self.stopping.load(Ordering::Acquire)
157	    }
158	    fn stop(&self) {
159	        let _guard = self.mutex.lock().unwrap_or_else(|error| error.into_inner());
160	        self.stopping.store(true, Ordering::Release);
161	        self.changed.notify_all();
162	    }
163	    fn pause(&self) {
164	        let guard = self.mutex.lock().unwrap_or_else(|e| e.into_inner());
165	        if !self.stopped() {
166	            let _ = self.changed.wait_timeout(guard, RETRY_INTERVAL);
167	        }
168	    }
169	}
