171	/// One worker, eight queued jobs, eight queued outcomes and at most one active
172	/// launch/unsent outcome. Root must also cap children plus pending operations.
173	pub struct SpawnWorker {
174	    sender: Option<SyncSender<SpawnJob>>,
175	    control: Arc<Control>,
176	    thread: Option<JoinHandle<()>>,
177	}
178	impl SpawnWorker {
179	    pub fn new() -> io::Result<(Self, Channel<SpawnOutcome>)> {
180	        Self::with_launcher(launch)
181	    }
182	
183	    fn with_launcher(
184	        launcher: impl FnMut(SpawnJob) -> io::Result<ManagedChild> + Send + 'static,
185	    ) -> io::Result<(Self, Channel<SpawnOutcome>)> {
186	        // calloop 0.14.5 exposes only an infallible channel constructor and panics
187	        // when its notifier cannot be created. Translate that resource failure
188	        // without mutating the process-global panic hook.
189	        let (completion_sender, completion_receiver) = std::panic::catch_unwind(|| {
190	            calloop::channel::sync_channel::<SpawnOutcome>(COMPLETION_CAPACITY)
191	        })
192	        .map_err(|_| io::Error::other("could not create application completion channel"))?;
193	        let (sender, receiver) = mpsc::sync_channel(QUEUE_CAPACITY);
194	        let control = Arc::new(Control {
195	            stopping: AtomicBool::new(false),
196	            mutex: Mutex::new(()),
197	            changed: Condvar::new(),
198	        });
199	        let thread_control = control.clone();
200	        let thread = thread::Builder::new()
201	            .name("flux-spawn".into())
202	            .spawn(move || run(receiver, completion_sender, thread_control, launcher))?;
203	        Ok((
204	            Self {
205	                sender: Some(sender),
206	                control,
207	                thread: Some(thread),
208	            },
209	            completion_receiver,
210	        ))
211	    }
212	
213	    /// Nonblocking admission only; acceptance does not mean exec completed.
214	    /// Job identity uniqueness and compositor lock/permission checks belong to Root.
215	    pub fn try_spawn(&self, job: SpawnJob) -> Result<(), Error> {
216	        if self.control.stopped() {
217	            return Err(Error::Stopped);
218	        }
219	        job.validate()?;
220	        match self.sender.as_ref().ok_or(Error::Stopped)?.try_send(job) {
221	            Ok(()) => Ok(()),
222	            Err(TrySendError::Full(_)) => Err(Error::QueueFull),
223	            Err(TrySendError::Disconnected(_)) => {
224	                self.control.stop();
225	                Err(Error::Stopped)
226	            }
227	        }
228	    }
229	    pub fn is_stopped(&self) -> bool {
230	        self.control.stopped()
231	    }
232	    /// Explicit blocking shutdown for reporting worker failure. Already delivered
233	    /// outcomes/children belong to the receiver and are not reclaimed by this call.
234	    pub fn shutdown(mut self) -> io::Result<()> {
235	        self.stop_and_join()
236	    }
237	    fn stop_and_join(&mut self) -> io::Result<()> {
238	        self.control.stop();
239	        self.sender.take();
240	        if let Some(thread) = self.thread.take() {
241	            thread
242	                .join()
243	                .map_err(|_| io::Error::other("application spawn worker panicked"))?;
244	        }
245	        Ok(())
246	    }
247	}
248	impl Drop for SpawnWorker {
249	    fn drop(&mut self) {
250	        let _ = self.stop_and_join();
251	    }
252	}
253	fn run(
254	    receiver: Receiver<SpawnJob>,
255	    completion: CompletionSender<SpawnOutcome>,
256	    control: Arc<Control>,
257	    mut launcher: impl FnMut(SpawnJob) -> io::Result<ManagedChild>,
258	) {
259	    'worker: while !control.stopped() {
260	        let job = match receiver.recv() {
261	            Ok(job) => job,
262	            Err(_) => break,
263	        };
264	        if control.stopped() {
265	            break;
266	        }
267	        let operation = job.operation;
268	        let mut outcome = SpawnOutcome {
269	            operation,
270	            result: launcher(job).map_err(|error| error.to_string()),
271	        };
272	        loop {
273	            // Delivery and stop are linearized: a result sent before stop is
274	            // receiver-owned; an active result after stop is killed/reaped here.
275	            let delivery = {
276	                let guard = control
277	                    .mutex
278	                    .lock()
279	                    .unwrap_or_else(|error| error.into_inner());
280	                if control.stopped() {
281	                    drop(guard);
282	                    drop(outcome);
283	                    break 'worker;
284	                }
285	                completion.try_send(outcome)
286	            };
287	            match delivery {
288	                Ok(()) => break,
289	                Err(TrySendError::Full(pending)) => {
290	                    outcome = pending;
291	                    control.pause();
292	                }
293	                Err(TrySendError::Disconnected(undelivered)) => {
294	                    drop(undelivered);
295	                    control.stop();
296	                    break 'worker;
297	                }
298	            }
299	        }
300	    }
301	    // Dropping receiver discards queued SpawnJob data without executing it.
302	}
