                TimeoutAction::Drop
            })
            .map_err(|e| std::io::Error::other(e.to_string()))?;
    }
    state.init_ipc(
        &event_loop.handle(),
        &runtime,
        options.socket.as_deref().ok_or("missing instance")?,
    )?;
    state.init_processes(&event_loop.handle())?;
    let source = config_source(
        options.config,
        options.no_config,
        std::env::var_os("XDG_CONFIG_HOME"),
        std::env::var_os("HOME"),
    )?;
